import json, numpy as np
a = json.load(open('/tmp/base.json')); b = json.load(open('/tmp/new.json'))
assert set(a) == set(b)
worst = (0.0, None)
bad = []
for k in a:
    if isinstance(a[k], str) or isinstance(b[k], str):
        if a[k] != b[k]: bad.append((k, a[k], b[k]))
        continue
    for combo in a[k]:
        x = np.array(a[k][combo]); y = np.array(b[k][combo])
        if x.shape != y.shape: bad.append((k, combo, 'shape')); continue
